from pathlib import Path
try:
    print(Path("note.txt").read_text(encoding="utf-8"))
except FileNotFoundError:
    print("note.txt absent")

from dataclasses import dataclass

@dataclass(frozen=True)
class Livre:
    titre: str
    pages: int

    def __post_init__(self):
        if not self.titre.strip() or self.pages < 0:
            raise ValueError("livre invalide")

livre = Livre("Web", 120)
print(livre.titre, livre.pages)

try:
    Livre("", -1)
except ValueError as erreur:
    print(type(erreur).__name__)  # ValueError
